def skill(robot):
    places = robot.places()
    inv = robot.inventory_record()
    items = list(inv.keys())
    found = {}
    for p in places:
        r = robot.drone_scan(p, items)
        if r:
            for it in r:
                found[it] = p
    for it in list(items):
        if it not in found:
            for p in places:
                r = robot.drone_scan(p, [it])
                if r and it in r:
                    found[it] = p
                    break
    miss = []
    for it, should in inv.items():
        act = found.get(it)
        if act is None:
            miss.append(it)
        elif act != should:
            ok = False
            for _ in range(2):
                if robot.go_to(act) and robot.pick(it):
                    ok = True
                    break
                s = robot.drone_scan(act, [it])
                if not s or it not in s:
                    n = robot.recall(it)
                    if n in places:
                        act = n
                    else:
                        ok = False
                        break
            if not ok:
                continue
            if robot.go_to(should):
                robot.put_aside()
    if miss:
        robot.report("missing: " + ", ".join(m + " (should be at " + str(inv[m]) + ")" for m in miss))
    robot.start_driving()
    return robot.land_on_moving_robot()
